import{_ as o,o as d,c as t,a3 as a}from"./chunks/framework.I6s8z2kk.js";const h=JSON.parse('{"title":"Support: OTP, devices and media","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/support.md","filePath":"dev/domain/support.md"}'),s={name:"dev/domain/support.md"};function n(c,e,i,r,l,p){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="support-otp-devices-and-media" tabindex="-1">Support: OTP, devices and media <a class="header-anchor" href="#support-otp-devices-and-media" aria-label="Permalink to &quot;Support: OTP, devices and media&quot;">​</a></h1><p>The <strong>Support</strong> module holds the shared building blocks.</p><h2 id="otp" tabindex="-1">OTP <a class="header-anchor" href="#otp" aria-label="Permalink to &quot;OTP&quot;">​</a></h2><p>All phone sign-in goes through <code>OtpVerificationService</code>.</p><ul><li>Codes are <strong>hashed</strong> and expire after <strong>300 seconds</strong>.</li><li>A new send invalidates older unused codes. A successful verify consumes the code.</li><li>Limits: <strong>5 sends per phone per 15 minutes</strong>, <strong>5 failed verifies per 5 minutes</strong>.</li><li>Use the same phone string for send, verify and account lookup.</li><li>Codes are always <strong>4 digits</strong> (the client verify request requires <code>digits:4</code>).</li></ul><h3 id="admin-issued-codes" tabindex="-1">Admin-issued codes <a class="header-anchor" href="#admin-issued-codes" aria-label="Permalink to &quot;Admin-issued codes&quot;">​</a></h3><p><code>issue()</code> creates a code for support staff to read to a user who is not receiving the SMS. It stores the code hashed like any other, invalidates older unused codes for the phone and returns the plain code once. It sends <strong>no SMS</strong> and skips the user-facing send limit; the admin routes are throttled to 10 per minute instead. It always writes a row, so the issued code also works for development phones.</p><p>Endpoints, both behind <code>otps.create</code>:</p><ul><li><code>POST admin/clients/{client}/otp</code>, for the client&#39;s <code>phone_number</code></li><li><code>POST admin/centers/{center}/users/{user}/otp</code>, for the center user&#39;s <code>phone</code>. The user must belong to the center, otherwise it returns 404.</li></ul><h3 id="development-bypass" tabindex="-1">Development bypass <a class="header-anchor" href="#development-bypass" aria-label="Permalink to &quot;Development bypass&quot;">​</a></h3><p>Works only when <code>otp.dev.enabled</code> is on, the environment is <code>local</code>, <code>testing</code> or <code>staging</code>, <strong>and</strong> the phone is in <code>OTP_DEV_PHONES</code>. Never widen it.</p><h2 id="devices-and-push-tokens" tabindex="-1">Devices and push tokens <a class="header-anchor" href="#devices-and-push-tokens" aria-label="Permalink to &quot;Devices and push tokens&quot;">​</a></h2><p>Register devices through <code>DeviceService::launch()</code> and link them on login with <code>attachTo()</code>. A device is unique per <code>(owner, identifier, platform)</code>. Invalid FCM tokens are <strong>nulled, not deleted</strong>.</p><p>Platforms are <code>ios</code>, <code>android</code> and <code>web</code>. Admins (browsers in the panel) register with <code>POST admin/devices</code> (<code>launch()</code> with the system user as owner, idempotent) and remove one with <code>DELETE admin/devices/{deviceIdentifier}</code>. <code>POST admin/auth/logout</code> revokes the current token and, when <code>X-Device-Identifier</code> (or <code>device_identifier</code>) is sent, removes that device too, so pushes to <code>SystemUser::notifiableAdmins()</code> stop reaching a signed-out browser.</p><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h2><p>Uploads go to <code>POST /api/v1/media</code> (the only endpoint that accepts several guards) and become <strong>temporary uploads</strong>. Attach client-supplied media only through <code>TemporaryMediaService::promote()</code> or <code>promoteMany()</code> (owner, expiry, lock, single use; <code>promoteMany</code> is all-or-nothing). Every media failure is reported as one 422 <code>InvalidTemporaryMediaException</code>. <code>DELETE media/{uuid}</code> removes an upload.</p><h2 id="system-users-roles-cities-and-tags" tabindex="-1">System users, roles, cities and tags <a class="header-anchor" href="#system-users-roles-cities-and-tags" aria-label="Permalink to &quot;System users, roles, cities and tags&quot;">​</a></h2><p>Admin CRUD for <code>system-users</code> (with <code>restore</code>), <code>system-roles</code>, <code>system-permissions</code> (read), <code>cities</code> and <code>tags</code>. See <a href="./../conventions/permissions">Roles and permissions</a>. Every admin policy denies inactive system users.</p><h2 id="activity-log" tabindex="-1">Activity log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity log&quot;">​</a></h2><p><code>admin/activity-logs</code> shows the audit trail (<code>activity_logs.view_any</code>). Translatable attributes are logged with every locale.</p><h2 id="legal-documents" tabindex="-1">Legal documents <a class="header-anchor" href="#legal-documents" aria-label="Permalink to &quot;Legal documents&quot;">​</a></h2><p><code>LegalDocument</code> holds the privacy policy and terms (<code>LegalDocumentType</code>: <code>privacy_policy</code>, <code>terms</code>) of each app (<code>LegalAudience</code>: <code>client</code>, <code>center</code>). The four rows are created by the migration and only updated; <code>content</code> is translatable HTML (en/ar), activity-logged as <code>legal_document</code>.</p><ul><li>Admin: <code>GET admin/legal-documents</code>, <code>GET|PUT admin/legal-documents/{audience}/{type}</code> with <code>legal_documents.manage</code>. A <code>PUT</code> needs both <code>content.en</code> and <code>content.ar</code> (max 200,000 characters each). <code>LegalHtmlSanitizer</code> (symfony/html-sanitizer) cleans the HTML before saving: safe elements only, no scripts or event handlers, links limited to http(s)/mailto/tel, <code>rel=&quot;noopener noreferrer&quot;</code> forced on links, and <code>style</code> reduced to <code>text-align</code>.</li><li>Public page: <code>GET /legal/{audience}/{type}?lang=en|ar</code> (<code>legal.show</code>, no auth, <code>web</code> group) renders <code>support::legal.show</code>, a standalone page with <code>dir=&quot;rtl&quot;</code> for Arabic. Unknown <code>lang</code> falls back to <code>en</code>; an empty document shows a &quot;not available yet&quot; note. Cached by clients for 5 minutes.</li><li>Apps: <code>GET client/legal</code> and <code>GET center/legal</code> (no token) return <code>privacy_policy_url</code> and <code>terms_url</code> in the <code>Accept-Language</code> locale (<code>en</code>/<code>ar</code>, default <code>en</code>) for the app to open in a webview.</li></ul><h2 id="documentation-access" tabindex="-1">Documentation access <a class="header-anchor" href="#documentation-access" aria-label="Permalink to &quot;Documentation access&quot;">​</a></h2><p><code>/docs</code> (endpoint reference) and <code>/guide</code> (these guides) are protected by a session login at <code>/docs/login</code> for active system users with <code>api_docs.view</code>. Five failed logins in a minute return 429.</p>',25)])])}const m=o(s,[["render",n]]);export{h as __pageData,m as default};
